166	/// Append `value` to a buffer, escaping the XML metacharacters that
167	/// `xmlwriter`'s raw attribute writer leaves untouched (it only escapes the
168	/// quotation mark). Otherwise a value such as a link URL containing `&` or `<`
169	/// yields malformed SVG. Runs of non-escaped characters are appended in one go.
170	fn escape_str(mut value: &str, mut append: impl FnMut(&str)) {
171	    while let Some((i, c)) = value
172	        .bytes()
173	        .enumerate()
174	        .find_map(|(i, b)| EscapedChar::from_byte(b).map(|c| (i, c)))
175	    {
176	        append(&value[..i]);
177	        append(c.escape_sequence());
178	
179	        // Escaped characters are always one byte.
180	        value = &value[i + 1..];
181	    }
182	    if !value.is_empty() {
183	        append(value);
184	    }
185	}
